"use client"

import animation from "react-useanimations/lib/rss"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "RSS" from https://useanimations.com (MIT): https://useanimations.com/icons/rss
export function AnimatedRss(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="hover-replay"
      {...props}
    />
  )
}
